LOCK TABLES `notif` WRITE;
/*!40000 ALTER TABLE `notif` DISABLE KEYS */;
INSERT INTO `notif` VALUES (1,'<p>کلی آزمون روان شناسی به سامانه مون اضافه کردیم که کلیش هم رایگانه.</p>\r\n<p>دوست داری یه سری بزن</p>\r\n<center>\r\n<a href=\"http://echeck.ir/ravanQuizes\" class=\"btn btn-success\" style=\"background-color: #00AF87; border-color: #00AF87; color: white\">\r\n  ایول، بزن بریم\r\n</a>\r\n</center>\r\n\r\n<p style=\"margin-top: 20px\">\r\n  اگه الان حال نداشتی بعدا هم می تونی از تو منو بخش آزمون های روان شناسی رو انتخاب کنی و از خودت تست بگیری\r\n</p>\r\n',1,1,'13990215');
/*!40000 ALTER TABLE `notif` ENABLE KEYS */;
UNLOCK TABLES;

