DROP TABLE IF EXISTS `quizRegistry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `quizRegistry` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `uId` int(11) NOT NULL,
  `qId` int(11) NOT NULL,
  `quizMode` int(11) NOT NULL,
  `timeEntry` varchar(16) NOT NULL,
  `online` tinyint(1) NOT NULL DEFAULT '1',
  `endTime` varchar(20) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `uId` (`uId`),
  KEY `qId` (`qId`),
  CONSTRAINT `qIdForeignInQuizRegistry` FOREIGN KEY (`qId`) REFERENCES `regularQuiz` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `uIdForeignInquizRegistry` FOREIGN KEY (`uId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9217 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

