DROP TABLE IF EXISTS `regularQuiz`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `regularQuiz` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `startDate` varchar(8) NOT NULL,
  `endDate` varchar(8) NOT NULL,
  `startTime` varchar(4) NOT NULL,
  `endTime` varchar(4) NOT NULL,
  `name` varchar(40) NOT NULL,
  `ranking` int(11) NOT NULL DEFAULT '10',
  `attach` varchar(1000) DEFAULT NULL,
  `video` varchar(400) DEFAULT NULL,
  `external` tinyint(1) NOT NULL DEFAULT '0',
  `userId` int(11) NOT NULL,
  `file` varchar(200) NOT NULL,
  `type` int(1) NOT NULL,
  `crop` tinyint(1) NOT NULL DEFAULT '1',
  `qNo` int(11) NOT NULL DEFAULT '0',
  `totalLen` int(11) NOT NULL DEFAULT '0',
  `sfile` varchar(100) DEFAULT NULL,
  `subject` int(11) NOT NULL DEFAULT '-1',
  `minus` tinyint(1) NOT NULL DEFAULT '1',
  `permutation` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `userId` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=206 DEFAULT CHARSET=utf8;
